<?php if(!empty($enrollment)): ?><p class="panel" style="padding:14px"><strong><?= htmlspecialchars(\App\Services\CommerceDetails::label($enrollment['payment_status']??'unpaid')) ?></strong> · <a href="/cours">Retrouver le reçu dans Mes formations</a></p><?php endif ?>
<?php
$previewMode = !empty($previewMode); $completedLessons = $completedLessons ?? []; $progress = (int) ($enrollment['progress'] ?? 0);
$lessonHref = static fn(array $lesson): string => $previewMode ? '/admin/cours/apercu-lecon?id='.(int)$lesson['id'] : '/academie/lecon?id='.(int)$lesson['id'];
?>
<?php if($previewMode): ?><div class="admin-preview-banner"><div><b>Mode aperçu administrateur</b><span>Vous consultez le contenu sans inscription et sans modifier la progression d’un étudiant.</span></div><div><a class="btn secondary" href="/admin/cours/programme?course=<?= (int)$course['id'] ?>">Modifier le programme</a><a class="btn secondary" href="/admin/cours">Quitter l’aperçu</a></div></div><?php endif ?>
<section class="student-course-head"><div><p class="eyebrow"><?= $previewMode?'APERÇU DU COURS':'MON COURS' ?></p><h1><?= htmlspecialchars($course['title']) ?></h1><p><?= $previewMode?'Vérifiez le programme et ouvrez chaque leçon depuis votre BackOffice.':'Avancez simplement, une leçon après l’autre.' ?></p></div><?php if(!$previewMode): ?><div class="course-progress-ring" style="--value:<?= $progress ?>"><strong><?= $progress ?>%</strong><small>terminé</small></div><?php endif ?></section>
<?php if(!$previewMode&&!empty($nextLesson)): ?><section class="next-lesson-card"><div><span>À SUIVRE MAINTENANT</span><h2><?= htmlspecialchars($nextLesson['title']) ?></h2><p><?= (int)$nextLesson['duration'] ?> minutes · <?= htmlspecialchars(ucfirst($nextLesson['type'])) ?></p></div><a class="btn primary" href="<?= $lessonHref($nextLesson) ?>"><?= $progress>0?'Continuer mon cours':'Commencer mon cours' ?> →</a></section><?php endif ?>
<div class="academy-sections"><?php foreach($modules as $i=>$module): ?><section class="panel academy-section"><header><span><?= $i+1 ?></span><div><h2><?= htmlspecialchars($module['title']) ?></h2><p><?= count($module['lessons']) ?> leçon(s)</p></div></header><?php foreach($module['lessons'] as $lesson): $isDone=in_array((int)$lesson['id'],$completedLessons,true); ?><article class="<?= $isDone?'lesson-done':'' ?>"><span><?= $isDone?'✓':($lesson['type']==='video'?'▶':($lesson['type']==='text'?'¶':'↓')) ?></span><div><strong><?= htmlspecialchars($lesson['title']) ?></strong><small><?= $isDone?'Terminée · ':'' ?><?= htmlspecialchars(ucfirst($lesson['type'])) ?> · <?= (int)$lesson['duration'] ?> min</small></div><a class="btn secondary" href="<?= $lessonHref($lesson) ?>"><?= $previewMode?'Prévisualiser':($isDone?'Revoir':'Ouvrir') ?></a></article><?php endforeach ?><?php if($module['assessment']): ?><article class="composition"><span>?</span><div><strong><?= htmlspecialchars($module['assessment']['title']) ?></strong><small>QCM · seuil <?= (int)$module['assessment']['passing_score'] ?>%</small></div><?php if($previewMode): ?><span class="preview-note">Visible par l’étudiant</span><?php else: ?><a class="btn primary" href="/academie/composition?id=<?= (int)$module['assessment']['id'] ?>">Composer</a><?php endif ?></article><?php endif ?></section><?php endforeach ?><?php if(!$modules): ?><div class="panel admin-empty">Le programme de cette formation est en préparation.</div><?php endif ?><?php if($final): ?><section class="panel final-exam"><div><p class="eyebrow">EXAMEN FINAL</p><h2><?= htmlspecialchars($final['title']) ?></h2><p>La réussite déclenche automatiquement le diplôme IFMAP.</p></div><?php if($previewMode): ?><span class="preview-note">Aperçu uniquement</span><?php else: ?><a class="btn primary" href="/academie/composition?id=<?= (int)$final['id'] ?>">Commencer l’examen</a><?php endif ?></section><?php endif ?></div>
<style>.admin-preview-banner{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:16px 20px;margin-bottom:22px;border:1px solid #cbe7dc;border-radius:16px;background:#effaf5}.admin-preview-banner>div:first-child{display:flex;flex-direction:column;gap:3px}.admin-preview-banner span,.admin-preview-banner b{font-size:11px}.admin-preview-banner>div:last-child{display:flex;gap:8px}.student-course-head{display:flex;align-items:center;justify-content:space-between;gap:25px;margin-bottom:22px}.student-course-head h1{font-size:clamp(25px,3vw,38px);margin:6px 0}.student-course-head>div>p:last-child{color:var(--muted)}.course-progress-ring{--value:0;width:104px;height:104px;flex:none;border-radius:50%;display:grid;place-content:center;text-align:center;background:radial-gradient(closest-side,#fff 78%,transparent 80% 99%),conic-gradient(var(--primary) calc(var(--value)*1%),#e8ecea 0)}.course-progress-ring strong{font-size:22px}.course-progress-ring small{color:var(--muted)}.next-lesson-card{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px 28px;margin-bottom:24px;border-radius:20px;color:#fff;background:linear-gradient(135deg,var(--primary),#205f56);box-shadow:0 18px 40px rgba(20,70,62,.18)}.next-lesson-card span{font-size:9px;letter-spacing:1.3px;opacity:.75}.next-lesson-card h2{font-size:20px;margin:6px 0}.next-lesson-card p{margin:0;opacity:.8}.next-lesson-card .btn{background:#fff;color:var(--primary);border:0}.academy-sections{display:flex;flex-direction:column;gap:15px}.academy-section{overflow:hidden;border-radius:18px}.academy-section header,.academy-section article{display:flex;align-items:center;gap:14px;padding:17px 20px;border-bottom:1px solid var(--line)}.academy-section header>span,.academy-section article>span:first-child{width:34px;height:34px;flex:none;border-radius:11px;display:grid;place-items:center;background:#eef4f1;color:var(--primary);font-weight:700}.academy-section header>span{border-radius:50%;background:var(--primary);color:#fff}.academy-section h2{font-size:15px;margin:0}.academy-section p,.academy-section small{color:var(--muted);margin:0}.academy-section article div{display:flex;flex:1;flex-direction:column;gap:3px}.academy-section article.lesson-done{background:#f7fcfa}.academy-section article.lesson-done>span:first-child{background:#dff5ea;color:#168257}.composition{background:#faf9ff}.preview-note{color:var(--muted);font-size:10px}.final-exam{padding:25px;display:flex;align-items:center;justify-content:space-between;border-radius:18px}@media(max-width:700px){.admin-preview-banner,.student-course-head,.next-lesson-card,.final-exam{align-items:flex-start;flex-direction:column}.admin-preview-banner>div:last-child{flex-wrap:wrap}.course-progress-ring{width:82px;height:82px;position:absolute;right:18px}.next-lesson-card .btn{width:100%}.academy-section article{padding:14px 12px}.academy-section article .btn{padding:0 11px}.student-course-head{padding-right:90px}}</style>
